const wrap = (body, cls='')=>`<svg class="game-art ${cls}" viewBox="0 0 240 138" fill="none" aria-hidden="true">${body}</svg>`;
export function art(id){
 const tile=(x,y,t,c='#fff')=>`<rect x="${x}" y="${y}" width="38" height="38" rx="9" fill="${c}"/><text x="${x+19}" y="${y+25}" text-anchor="middle" fill="#245de8" font-size="19" font-weight="600">${t}</text>`;
 if(id==='numerosity')return wrap(tile(44,50,7)+tile(101,29,5)+tile(158,50,9)+`<path d="M92 72h9m-4-4v8M148 72h9m-4-4v8" stroke="#6c8fed" stroke-width="2"/><rect x="90" y="88" width="61" height="28" rx="14" fill="#245de8"/><text x="120" y="107" text-anchor="middle" fill="white" font-size="15">12</text>`);
 if(id==='digitspan')return wrap([3,8,2,6].map((n,i)=>tile(28+i*48,50,n,i===2?'#245de8':'white').replace(i===2?'fill="#245de8" font-size':'unused',i===2?'fill="white" font-size':'unused')).join('')+`<path d="M80 105h80" stroke="#b4c7f8" stroke-width="3" stroke-linecap="round"/>`);
 if(id==='flashback')return wrap(`<rect x="48" y="42" width="54" height="54" rx="14" fill="white" opacity=".6"/><rect x="134" y="42" width="54" height="54" rx="14" fill="white"/><path d="m75 55 14 14-14 14-14-14Zm86 0 14 14-14 14-14-14Z" fill="#6863d8"/><path d="M111 66h14m-14 7h14" stroke="#ada9e8" stroke-width="2"/>`);
 if(id==='pathfinder')return wrap(`<path d="M46 92h47V46h48v46h49" stroke="#beddd3" stroke-width="34" stroke-linejoin="round"/><path d="M46 92h47V46h48v46h49" stroke="#25896d" stroke-width="8" stroke-linejoin="round"/><circle cx="46" cy="92" r="8" fill="#25896d"/><circle cx="190" cy="92" r="8" fill="white" stroke="#25896d" stroke-width="3"/>`);
 if(id==='disconumbers')return wrap([2,4,7,3,9].map((n,i)=>`<circle cx="${45+i*38}" cy="${i%2?45:86}" r="20" fill="${i===2?'#6b62cf':'white'}"/><text x="${45+i*38}" y="${i%2?51:92}" text-anchor="middle" fill="${i===2?'white':'#6b62cf'}" font-size="17">${n}</text>`).join(''));
 if(id==='puzzle')return wrap(`<rect x="72" y="27" width="44" height="40" rx="5" fill="#79afa2"/><rect x="122" y="27" width="44" height="40" rx="5" fill="#2d8270"/><rect x="72" y="73" width="44" height="40" rx="5" fill="#c1ded5"/><rect x="134" y="83" width="44" height="40" rx="5" fill="#549b8b" transform="rotate(12 156 103)"/>`);
 if(id==='shapedance')return wrap(`<path d="m72 35 24 41H48Z" fill="#318971"/><path d="m164 62 24 41h-48Z" fill="#318971"/><rect x="125" y="22" width="32" height="32" rx="7" fill="#b4d6ca"/><circle cx="91" cy="101" r="18" fill="#a7c8e8"/>`);
 if(id==='singularity')return wrap([0,1,2,3,4,5].map((_,i)=>`<path d="m${68+(i%3)*50} ${35+Math.floor(i/3)*50} 15 15-15 15-15-15Z" fill="${i===4?'#245de8':'#b1c9e1'}" ${i===4?`transform="rotate(45 118 100)"`:''}/>`).join(''));
 if(id==='pulse')return wrap(`<path d="M30 76h49l11-26 18 52 18-67 17 41h65" stroke="#a8bded" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="143" cy="76" r="12" fill="#df6569"/>`);
 if(id==='portraitxt')return wrap(`<rect x="61" y="24" width="118" height="91" rx="10" fill="white"/><path d="M80 47h76M80 62h49" stroke="#adc0df" stroke-width="5" stroke-linecap="round"/>${[0,1,2,3,4].map((n)=>`<circle cx="${81+n*19}" cy="88" r="6" fill="${n===3?'#245de8':'#e0e9f8'}"/>`).join('')}`);
 if(id==='teamchat')return wrap(`<rect x="41" y="29" width="113" height="36" rx="12" fill="white"/><path d="M57 47h71" stroke="#b3c6eb" stroke-width="5" stroke-linecap="round"/><rect x="91" y="76" width="109" height="36" rx="12" fill="#587dc7"/><path d="M108 94h69" stroke="white" stroke-width="5" stroke-linecap="round"/>`);
 if(id==='emotions')return wrap(`<circle cx="120" cy="69" r="42" fill="#f8d19b"/><circle cx="106" cy="60" r="3" fill="#745234"/><circle cx="134" cy="60" r="3" fill="#745234"/><path d="M103 78q17 19 34 0" stroke="#745234" stroke-width="3" stroke-linecap="round"/>`);
 return wrap(`<rect x="50" y="35" width="56" height="70" rx="11" fill="white"/><rect x="134" y="35" width="56" height="70" rx="11" fill="white"/><circle cx="78" cy="59" r="10" fill="#899bc4"/><path d="M63 89q15-25 30 0" fill="#899bc4"/><circle cx="156" cy="60" r="8" fill="#d1a273"/><circle cx="172" cy="72" r="8" fill="#82a899"/><path d="M144 89q14-23 27 0M158 100q14-23 27 0" fill="#82a899"/>`);
}
